<script lang="ts" module>import type { Snippet } from 'svelte'; export interface StepProps { title:string; description?:string; icon?:Snippet; disabled?:boolean; error?:boolean; optional?:boolean; children?:Snippet; }</script>
<script lang="ts">import { getStepsContext } from './context'; let {title,description,icon,disabled=false,error=false,optional=false,children}:StepProps=$props(); const ctx=getStepsContext(); const index=ctx.register({get title(){return title},get description(){return description},get icon(){return icon},get disabled(){return disabled},get error(){return error},get optional(){return optional}}); const state=$derived(ctx.state()); const status=$derived(error?'error':index<state.current?'completed':index===state.current?'current':'pending');function ripple(e:PointerEvent){if(disabled||!state.clickable)return;const button=e.currentTarget as HTMLElement,rect=button.getBoundingClientRect(),x=e.clientX-rect.left,y=e.clientY-rect.top,r=Math.max(Math.hypot(x,y),Math.hypot(rect.width-x,y),Math.hypot(x,rect.height-y));const drop=document.createElement('span');drop.className='rx-step__ripple';drop.style.cssText=`left:${x}px;top:${y}px;width:${r*2}px;height:${r*2}px`;button.append(drop);drop.addEventListener('animationend',()=>drop.remove(),{once:true})}</script>
