 <button type="button" disabled={disabled || !state.clickable} aria-label={`Step ${index+1}: ${title}`} onpointerdown={ripple} onclick={()=>ctx.choose(index)}><span class="rx-step__mark"><svg class="rx-step__ring" viewBox="0 0 36 36" aria-hidden="true"><circle cx="18" cy="18" r="15"/><circle class="rx-step__ring-progress" cx="18" cy="18" r="15"/></svg><span class="rx-step__number">{#if icon}{@render icon()}{:else}{index+1}{/if}</span><span class="rx-step__check" aria-hidden="true">✓</span></span><span class="rx-step__copy"><strong>{title}</strong>{#if optional}<small>Optional</small>{/if}{#if description}<span>{description}</span>{/if}</span></button>{#if children}<div class="rx-step__content">{@render children()}</div>{/if}
</li>
